import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.DA69LXMH.js";const g=JSON.parse('{"title":"Histórico de Versões & Releases","description":"","frontmatter":{},"headers":[],"relativePath":"suporte/changelog.md","filePath":"suporte/changelog.md"}'),i={name:"suporte/changelog.md"};function t(n,o,d,l,c,m){return e(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="historico-de-versoes-releases" tabindex="-1">Histórico de Versões &amp; Releases <a class="header-anchor" href="#historico-de-versoes-releases" aria-label="Permalink to &quot;Histórico de Versões &amp; Releases&quot;">​</a></h1><p>Acompanhe as principais novidades, marcos arquiteturais e melhorias de estabilidade adicionadas ao ecossistema do <strong>EchoBot</strong>.</p><hr><h2 id="🚀-versao-1-9-0-versao-atual-estavel" tabindex="-1">🚀 Versão 1.9.0 (Versão Atual Estável) <a class="header-anchor" href="#🚀-versao-1-9-0-versao-atual-estavel" aria-label="Permalink to &quot;🚀 Versão 1.9.0 (Versão Atual Estável)&quot;">​</a></h2><h3 id="🗺️-worldbuilding-colaboracao" tabindex="-1">🗺️ Worldbuilding &amp; Colaboração <a class="header-anchor" href="#🗺️-worldbuilding-colaboracao" aria-label="Permalink to &quot;🗺️ Worldbuilding &amp; Colaboração&quot;">​</a></h3><ul><li><strong>Hierarquia Canônica de 3 Níveis:</strong> Suporte estruturado a Mundos (Cenários/Sistemas de Regras), Campanhas (Crônicas) e Sessões.</li><li><strong>Portal do Jogador &amp; Colaboração Segura:</strong> Portal mobile dedicado (<code>/player</code>) para consulta de lore pública e envio de propostas de novos artigos com moderação em tempo real (diff visual estilo Git).</li><li><strong>Firewall Remoto do Mestre:</strong> Isolamento automático bloqueando acessos externos a telas administrativas e configurações.</li><li><strong>Grafo de Conhecimento Interativo (React Flow):</strong> Visualização e edição de conexões entre entidades, filtros por categoria e salvamento de coordenadas 2D.</li><li><strong>Linhagens &amp; Genealogia (D3.js):</strong> Visualizador de árvores genealógicas e organogramas dinásticos interativos.</li><li><strong>Oráculo Semântico do Mundo (World RAG):</strong> Busca vetorial local com álgebra linear em NumPy agregando compêndio e histórico de sessões.</li></ul><h3 id="🎙️-processamento-acustico-voz" tabindex="-1">🎙️ Processamento Acústico &amp; Voz <a class="header-anchor" href="#🎙️-processamento-acustico-voz" aria-label="Permalink to &quot;🎙️ Processamento Acústico &amp; Voz&quot;">​</a></h3><ul><li><strong>Aceleração STT com Whisper Large-v3-Turbo:</strong> Adoção do modelo Turbo como padrão, proporcionando ganho de até 6x em velocidade com baixo consumo de VRAM em GPUs NVIDIA CUDA.</li><li><strong>Identificação Biométrica de Vozes (Speaker ID):</strong> Pipeline acelerada por GPU para correlacionar padrões vocais aos personagens cadastrados em menos de 3 minutos.</li><li><strong>Gravador WebRTC no Navegador:</strong> Captação de áudio diretamente pela interface web com suporte a microfone e loopback do áudio do sistema.</li><li><strong>Importação e Exportação de Transcrição (.md):</strong> Parser inteligente para ingestão de transcrições externas com timestamps e oradores.</li></ul><h3 id="📦-infraestrutura-portabilidade" tabindex="-1">📦 Infraestrutura &amp; Portabilidade <a class="header-anchor" href="#📦-infraestrutura-portabilidade" aria-label="Permalink to &quot;📦 Infraestrutura &amp; Portabilidade&quot;">​</a></h3><ul><li><strong>Banco de Dados Flat-File (&quot;Zero-Config&quot;):</strong> Abstração dual para persistência em JSON atômico sem exigir instalação do MongoDB.</li><li><strong>Assistente de Migração de Armazenamento:</strong> Monitoramento de uso de disco e transferência segura da pasta <code>%LOCALAPPDATA%\\EchoBotData</code> para outras unidades.</li><li><strong>Atualizador Interno In-App (1-Click Auto-Updater):</strong> Verificação de novas versões no GitHub Releases com download e instalação silenciosa.</li><li><strong>Console Administrativo de Logs (<code>/logs</code>):</strong> Streaming de eventos em tempo real com filtros por componente e exportação em <code>.txt</code>.</li><li><strong>11 Temas Visuais &amp; i18n Completo:</strong> Suporte a temas de fantasia e ficção e internacionalização integral em Português (PT-BR) e Inglês (en-US).</li></ul><hr><h2 id="🏛️-versao-1-0-0-fundacao-do-sistema" tabindex="-1">🏛️ Versão 1.0.0 (Fundação do Sistema) <a class="header-anchor" href="#🏛️-versao-1-0-0-fundacao-do-sistema" aria-label="Permalink to &quot;🏛️ Versão 1.0.0 (Fundação do Sistema)&quot;">​</a></h2><ul><li><strong>Voice Bridge para Discord (Node.js):</strong> Captura de canais de voz em faixas separadas via comandos <code>/entrar</code> e <code>/sair</code>.</li><li><strong>Conversão Ogg/Opus:</strong> Otimização acústica reduzindo o tamanho dos arquivos em até 90%.</li><li><strong>Síntese de Voz Kokoro Local (ONNX):</strong> Narração de resumos 100% offline, gratuita e sem custos de API.</li><li><strong>Diário Técnico Automatizado:</strong> Extração de NPCs, Locais, Itens e Quests com máquina de estados.</li><li><strong>Roteiro Épico &amp; Trilha Sonora:</strong> Geração de crônica de revisão com trilha musical royalty-free integrada.</li><li><strong>Exportação:</strong> Suporte a arquivos PDF estilizados, Markdown e integração com Notion.so.</li></ul>',13)])])}const p=a(i,[["render",t]]);export{g as __pageData,p as default};
